SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

UPDATE `custom_pages_i18n`
SET `content` = JSON_OBJECT(
  'html',
  CONCAT(
    JSON_UNQUOTE(JSON_EXTRACT(`content`, '$.html')),
    '<h2>11. Cocuklara ait veriler</h2><p>PaketJet hizmeti genel olarak eriskin kullanicilar icin tasarlanmistir. Reşit olmayan kisilere ait verilerin bilerek toplanmasi hedeflenmez. Buna ragmen bir destek kaydi ya da acik metin formu uzerinden boyle bir veri paylasimi fark edilirse, ilgili kayitlar durumun niteligine gore sinirlandirilir veya silme surecine alinabilir. Ebeveyn veya yasal temsilci, boyle bir veri aktarimi suphelendiginde iletisim kanallarimiz uzerinden basvuru yapabilir.</p><h2>12. Yurt disi aktarim yaklasimi</h2><p>Altyapi ve barindirma ihtiyaclari, analiz servisleri veya guvenlik araclari nedeniyle bazi teknik hizmetler yurt disi baglantili olabilir. Bu durumda aktarim; mevzuata uygun guvenceler, gerekli teknik onlemler ve veri minimizasyonu prensibiyle sinirli tutulur. PaketJet, aktarim gerektirmeyen cozumleri tercih etmeye calisir; aktarim zorunlu ise kullanici verisinin kapsamini azaltan ve erisim yetkisini kisitlayan modeller kullanir.</p><h2>13. Ozel durumlarda isleme</h2><p>Dolandiricilik supheleri, guvenlik ihlalleri, odeme ihtilaflari veya hukuki uyusmazliklarda normal operasyon sirasinda kullanilmayan bazi kayitlar incelemeye acilabilir. Bu inceleme gelişi guzel degil, olayla sinirli ve kayit altinda ilerler. Yetkisiz personelin inceleme yapmamasi esastir. Amaç; delil niteligini korumak, hizli cozum saglamak ve olasi zarar ihtimalini azaltmaktir.</p><h2>14. Kullanici sorumlulugu</h2><p>Gizlilik korumasinin yalnizca platform teknikleriyle saglanamayacagi bilinmelidir. Kullanici; hesap sifresini paylasmamak, ortak cihazlarda oturumunu acik birakmamak, destek formlarina gereksiz hassas veri yazmamak ve iletisim detaylarini dogru guncellemekle de sorumludur. Basit guvenlik hijyeni, veri koruma surecinin onemli bir parcasidir.</p><h2>15. Basvuru ve iletisim kayitlari</h2><p>Gizlilik veya veri koruma talepleri destek ekiplerimiz tarafindan kayda alinabilir. Bu kayitlar, basvurunun alindigini gostermek, sure takibi yapmak ve yasal yukumlulukleri yerine getirmek icin tutulur. Basvurular yanitlandiktan sonra ilgili kayitlar da saklama politikasina uygun sekilde korunur. Boylece hem kullanicinin talebi kaybolmaz hem de surec denetlenebilir halde kalir.</p>'
  )
)
WHERE `page_id` = '55555555-5555-4555-8555-555555555552' AND `locale` = 'tr';

UPDATE `custom_pages_i18n`
SET `content` = JSON_OBJECT(
  'html',
  CONCAT(
    JSON_UNQUOTE(JSON_EXTRACT(`content`, '$.html')),
    '<h2>11. Basvuru usulu</h2><p>KVKK kapsamindaki talepler yazili basvuru, kayitli elektronik posta, guvenli elektronik imza veya veri sorumlusunca duyurulan diger yontemlerle iletilebilir. PaketJet, basvurunun gercek hak sahibi tarafindan yapildigini anlayabilmek icin ek kimlik dogrulama bilgisi isteyebilir. Bu kontrol, hem hak ihlalini onlemek hem de yetkisiz veri ifsasini engellemek icin uygulanir.</p><p>Basvuru iceriginde talebin konusu, ilgili hesap veya iletisim bilgileri, varsa destek kaydi numarasi ve talebe dayanak olusturan aciklamalarin yer almasi surecin hizli ilerlemesini saglar. Eksik bilgiyle gelen basvurularda ek aciklama istenebilir.</p><h2>12. Veri kategorilerine gore degerlendirme</h2><p>Her veri ayni sekilde degerlendirilmez. Hesap bilgileri, destek kayitlari, islem guvenligi loglari, odeme referanslari ve yasal saklama kayitlari farkli hukuki sebepler ve farkli saklama sureleri ile ele alinir. Bu nedenle bir silme ya da duzeltme talebinin sonucu, ilgili veri kategorisinin niteligine gore degisebilir. PaketJet, kullaniciya mumkun oldugunca acik ve gerekceli donus yapmayi hedefler.</p><h2>13. Acik riza gerektiren surecler</h2><p>Kanuni zorunluluklarin ve sozlesmenin ifasinin disina cikan belirli pazarlama veya tercih bazli surecler, acik riza gerektirebilir. Bu gibi durumlarda kullanici, hangi veri kategorisi icin hangi amacla onay verdigini anlayabilecek sekilde bilgilendirilir. Verilen acik riza, gelecege etkili olarak geri alinabilir. Rizanin geri alinmasi, geri alma tarihinden onceki hukuka uygun isleme faaliyetlerini gecersiz hale getirmez.</p><h2>14. Saklama kriterleri</h2><p>Saklama sureleri belirlenirken mevzuat, olasi uyusmazlik sureleri, bilgi guvenligi ihtiyaci, finansal mutabakat ve denetim gereksinimleri birlikte degerlendirilir. PaketJet, gereksiz veri biriktirmeme prensibiyle hareket eder. Buna ragmen bir hakkin tesisi veya korunmasi icin belirli kayitlarin bir sure daha tutulmasi gerekebilir. Bu durumda veri erisimi sinirlandirilir ve yalnizca yetkili personel tarafindan gorulebilir.</p><h2>15. Yurt ici ve yurt disi aktarim guvenceleri</h2><p>Kisisel verilerin ucuncu taraflarla paylasiminda veri isleyen iliskileri, gizlilik yukumlulugu, teknik guvenlik kontrolleri ve amac sinirlari dikkate alinir. Yurt disi baglantili hizmetlerde de aktarim dayanaklari ve teknik onlemler degerlendirilir. Gereksiz veri aktarimindan kacinilir, mumkun oldugunca sinirli veri alanlariyla calisilir.</p><h2>16. Olay yonetimi ve ihlal sureci</h2><p>Guvenlik ihlali suphelerinde olay kaydi olusturulur, teknik ekipler durumu inceler ve gerekli ise etki analizi yapilir. Mevzuatin gerektirdigi hallerde ilgili kurumlara ve kullanicilara bildirim yapilabilir. Amaç yalnizca reaktif hareket etmek degil, benzer olaylarin tekrar etmesini engelleyecek teknik ve idari duzeltmeleri de hayata gecirmektir.</p><h2>17. Ilgili kisi haklarinin sinirlari</h2><p>Kanun, belirli durumlarda ilgili kisi haklarinin mutlak sekilde kullanilamayabilecegini kabul eder. Ornegin yasal saklama zorunlulugu bulunan veriler derhal silinemeyebilir veya bir uyusmazlikta delil niteligindeki kayitlar korunabilir. PaketJet, bu gibi durumlarda talebi tamamen cevapsiz birakmaz; hangi sebeple neyin sinirlandirildigini aciklar.</p><h2>18. Son hukum</h2><p>Bu metin, kullanicinin sadece haklarini degil, verinin nasil yonetildigine dair genel sistemi de anlatmayi hedefler. PaketJet veri korumayi tek seferlik bir uyum metni olarak degil, urun, operasyon ve destek sureclerinin devamlilik gosteren bir parcasi olarak gorur.</p>'
  )
)
WHERE `page_id` = '55555555-5555-4555-8555-555555555553' AND `locale` = 'tr';

UPDATE `custom_pages_i18n`
SET `content` = JSON_OBJECT(
  'html',
  CONCAT(
    JSON_UNQUOTE(JSON_EXTRACT(`content`, '$.html')),
    '<h2>11. Delil ve kayit niteligindeki veriler</h2><p>Platform uzerindeki islem kayitlari, loglar, destek yazismalari ve rezervasyon verileri belirli uyusmazliklarda delil niteliginde degerlendirilebilir. Bu nedenle kullanici, sistemde biraktigi kayitlarin hukuki sureclerde dikkate alinabilecegini kabul eder. PaketJet da bu kayitlari guvenli ve olculu sekilde saklamaya gayret eder.</p><h2>12. Hizmet surekliligi</h2><p>PaketJet hizmetin surekliligini hedeflese de planli bakim, teknik ariza, guvenlik guncellemesi, ucuncu taraf entegrasyon kesintisi veya resmi zorunluluklar nedeniyle bazi ozellikleri gecici olarak durdurabilir. Boyle bir durumda platformun tum fonksiyonlari ayni anda kullanilamayabilir. Kullanici bu riskin dijital hizmet dogasinin bir parcasi oldugunu bilir.</p><h2>13. Kullanici icerikleri</h2><p>Kullanicilar tarafindan saglanan ilan, aciklama, destek notu ve benzeri iceriklerin hukuka, ahlaka ve platform kurallarina uygun olmasi gerekir. Hakaret, tehdit, aldatma, baskasina ait haklari ihlal eden aciklama veya yasadisi urun tanimlari kaldirilabilir. PaketJet bu icerikleri inceleme, duzeltme isteme veya yayindan kaldirma hakkina sahiptir.</p><h2>14. Ucuncu taraf baglantilar</h2><p>Platform zaman zaman ucuncu taraf hizmetlere, odeme sayfalarina veya harita servislerine yonlendirme icerebilir. Bu servislerin kendi kullanim kosullari ve gizlilik politikalar i bulunur. PaketJet, kendi kontrolu disindaki alanlarda kullanicinin yasadigi sorunlardan dogrudan sorumlu olmaz; ancak uygun oldugunda bilgilendirme saglayabilir.</p><h2>15. Mucbir sebep</h2><p>Dogal afet, savas, ayaklanma, genel telekom kesintisi, enerji sorunu, salgin, resmi makam karari, siber saldiri veya makul kontrol disindaki benzeri olaylar mucbir sebep sayilabilir. Bu hallerde hizmetin kismen veya tamamen aksamasindan kaynaklanan gecikmeler nedeniyle PaketJet derhal sorumlu tutulamaz. Yine de mumkun olan en kisa surede normallesme icin gerekli adimlar atilir.</p><h2>16. Ticari itibar ve guven</h2><p>Kullanicilarin platformu kotuye kullanmasi yalnizca tekil bir islem sorunu yaratmaz; tum ekosistemin guvenini etkiler. Bu nedenle sahte hesap, manipule edici yorum, sistem disi odeme zorlugu ve ilan kalitesini dusuren davranislar konusunda PaketJet daha katidir. Guven, hizmetin asli unsurlarindan biridir.</p><h2>17. Degisikliklerin yansimasi</h2><p>Kullanim kosullarinda degisiklik yapildiginda yeni metin platformda yayimlanir. Onemli degisiklikler ayrica dikkat cekici sekilde duyurulabilir. Kullanici, degisiklik sonrasinda platformu kullanmaya devam ederek guncel kosullari kabul etmis sayilir; ancak anlamadigi ya da itiraz ettigi noktalar icin destek kanalina basvurabilir.</p>'
  )
)
WHERE `page_id` = '55555555-5555-4555-8555-555555555554' AND `locale` = 'tr';

UPDATE `custom_pages_i18n`
SET `content` = JSON_OBJECT(
  'html',
  CONCAT(
    JSON_UNQUOTE(JSON_EXTRACT(`content`, '$.html')),
    '<h2>12. Paketleme ornekleri</h2><p>Elektronik urunler antistatik veya koruyucu katmanla sarilmali, kutu icinde bosluk kalmamalidir. Cam ve seramik urunlerde cift katman koruma ve darbe emici dolgu kullanilmalidir. Evrak benzeri gonderiler su gecirmez dosya veya sert zarfla hazirlanmalidir. Bu ornekler baglayici teknik standart yerine iyi uygulama rehberi niteligindedir; ancak olasi bir hasar degerlendirmesinde onemli referans olusturur.</p><h2>13. Bulusma ve teslim zamani planlama</h2><p>Tasima sadece arac hareketinden ibaret degildir. Bulusma noktasi, teslim alma saati, alicinin ulasilabilirligi ve varis noktasindaki operasyon da sureci etkiler. Taraflar randevu niteligindeki bilgileri gecikmeden teyit etmeli, degisiklik durumunda birbirini haberdar etmelidir. Aksi halde bekleme, ikinci bulusma ve uyusmazlik riski artar.</p><h2>14. Belgeleme ve fotograf kaydi</h2><p>Yuksek degerli veya hassas gonderilerde teslim oncesi fotograflama faydali olabilir. Paketli urunun dis gorunumu, paket sayisi ve teslim anindaki durum ileride olasi itirazlarda aciklayici rol oynar. PaketJet her gonderi icin zorunlu belge akisi dayatmaz; ancak kullanicilara kanit niteligindeki basit kayitlari tutmalarini onerir.</p><h2>15. Destek ekibinin rolu</h2><p>Destek ekibi, kurallari yorumlamak, sureci belgelemek ve olay bazli cozum aramak icin devreye girer. Bununla birlikte destek kanalinin varligi, taraflarin baslangicta acik bilgi verme yukumlulugunu ortadan kaldirmaz. En saglikli tasima, kurallarin en az ihlal edildigi ve beklentilerin bastan netlestirildigi surectir.</p>'
  )
)
WHERE `page_id` = '55555555-5555-4555-8555-555555555555' AND `locale` = 'tr';
